import gc

class Payload:
    def __init__(self, key):
        self.key = key
    def __eq__(self, other):
        return isinstance(other, Payload) and self.key == other.key

made = []
def factory(key):
    made.append(key)
    return Payload(key)

c = WeakCache(factory)
v1 = c.get('a')
assert v1.key == 'a' and made == ['a']
assert c.get('a') is v1  # still alive → same object, no rebuild
assert made == ['a']
print('ok')
